function Skills() {
  return (
    <div id="skills">
      <h2>Skills</h2>
      <ul>
        <li>React.js</li>
        <li>JavaScript (ES6+)</li>
        <li>HTML & CSS</li>
        <li>Node.js</li>
      </ul>
    </div>
  );
}

export default Skills;
